/**
 * src/editor/linter-logic.js
 * Static LaTeX analysis and linting:
 * - Undefined control sequences based on loaded packages & local definitions
 * - Nearest command suggestion (Levenshtein distance <= 2)
 * - Mismatched \begin{env} and \end{env}
 * - Unbalanced braces
 */

const fs = require('fs');
const path = require('path');

// Load database generated by scripts/build-latex-db.js
let COMMANDS_DB = null;
function getCommandsDb() {
  if (!COMMANDS_DB) {
    try {
      COMMANDS_DB = require('../../data/latex-commands.json');
    } catch (_) {}
    if (!COMMANDS_DB) {
      const candidates = [
        path.join(__dirname, '../../data/latex-commands.json'),
        path.join(__dirname, '../data/latex-commands.json'),
        path.join(__dirname, 'data/latex-commands.json'),
        path.resolve(process.cwd(), 'data/latex-commands.json')
      ];
      for (const p of candidates) {
        if (fs.existsSync(p)) {
          try {
            COMMANDS_DB = JSON.parse(fs.readFileSync(p, 'utf8'));
            break;
          } catch (_) {}
        }
      }
    }
    if (!COMMANDS_DB) {
      COMMANDS_DB = { macros: [], environments: [], packages: [] };
    }
    if (process.env.LACK_DEBUG) {
      console.log(`[LACK_DEBUG] Linter DB size: ${COMMANDS_DB.macros.length} macros, ${COMMANDS_DB.packages.length} packages`);
    }
  }
  return COMMANDS_DB;
}

// Levenshtein distance helper
function levenshteinDistance(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;

  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          matrix[i][j - 1] + 1,     // insertion
          matrix[i - 1][j] + 1      // deletion
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

/**
 * Extracts all loaded packages and document class from LaTeX text.
 */
function extractLoadedPackages(text) {
  const packages = new Set(['latex2e']);

  // Document class e.g. \documentclass[11pt]{article} or beamer
  const docClassMatch = text.match(/\\documentclass(?:\[[^\]]*\])?\{([^}]+)\}/);
  if (docClassMatch) {
    const cls = docClassMatch[1].trim();
    packages.add(cls);
    if (cls === 'beamer') packages.add('beamer');
    if (cls === 'amsart' || cls === 'amsbook') {
      packages.add('amsmath');
      packages.add('amssymb');
      packages.add('amsthm');
    }
  }

  // \usepackage[...]{pkg1, pkg2}
  const usepkgRegex = /\\usepackage(?:\[[^\]]*\])?\{([^}]+)\}/g;
  let m;
  while ((m = usepkgRegex.exec(text)) !== null) {
    const rawPkgs = m[1].split(',');
    for (let p of rawPkgs) {
      p = p.trim();
      if (p) packages.add(p);
    }
  }

  return packages;
}

/**
 * Extracts locally defined commands and environments:
 * \newcommand{\mycmd}, \def\mycmd, \DeclareMathOperator{\op}, etc.
 */
function extractLocalDefinitions(text, extraStyContent = '') {
  const localCommands = new Set();
  const localEnvironments = new Set();

  const combined = text + '\n' + extraStyContent;

  // \newcommand{\name}, \renewcommand{\name}, \providecommand{\name}
  const newcmdRegex = /\\(?:re|provide)?newcommand\*?\{?\\([a-zA-Z@]+)\}?/g;
  let m;
  while ((m = newcmdRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \def\name
  const defRegex = /\\def\\([a-zA-Z@]+)/g;
  while ((m = defRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \let\new=\old
  const letRegex = /\\let\\([a-zA-Z@]+)/g;
  while ((m = letRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \DeclareMathOperator{\op}{...}
  const opRegex = /\\DeclareMathOperator\*?\{?\\([a-zA-Z@]+)\}?/g;
  while ((m = opRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \newcounter{name} -> defines \thename
  const counterRegex = /\\newcounter\{([a-zA-Z0-9*_-]+)\}/g;
  while ((m = counterRegex.exec(combined)) !== null) {
    localCommands.add(`the${m[1]}`);
  }

  // \newenvironment{name}
  const newenvRegex = /\\(?:re)?newenvironment\*?\{([a-zA-Z0-9*_-]+)\}/g;
  while ((m = newenvRegex.exec(combined)) !== null) {
    localEnvironments.add(m[1]);
  }

  return { localCommands, localEnvironments };
}

/**
 * Runs the static diagnostic checks on a LaTeX document.
 * Returns an array of diagnostics compatible with CodeMirror 6 Lint:
 * { from, to, severity, message, line, actions: [{ name, apply }] }
 */
function lintLatexDocument(text, options = {}) {
  const diagnostics = [];
  if (!text || typeof text !== 'string') return diagnostics;

  const db = getCommandsDb();
  const loadedPackages = extractLoadedPackages(text);
  let extraStyContent = options.extraStyContent || '';
  if (options.preambleText && typeof options.preambleText === 'string') {
    for (const pkg of extractLoadedPackages(options.preambleText)) {
      loadedPackages.add(pkg);
    }
    extraStyContent += '\n' + options.preambleText;
  }
  const { localCommands, localEnvironments } = extractLocalDefinitions(text, extraStyContent);

  // Build the set of valid commands and environments
  const validCommands = new Set(localCommands);
  const validEnvironments = new Set(localEnvironments);
  const knownCommandNames = [];

  // Always include standard primitive/core commands
  validCommands.add('begin');
  validCommands.add('end');
  validCommands.add('item');
  validCommands.add('label');
  validCommands.add('ref');
  validCommands.add('cite');
  validCommands.add('documentclass');
  validCommands.add('usepackage');

  // Core standard LaTeX2e math delimiters, accents, font sizing & TeX primitives (no extra package needed)
  const CORE_LATEX_COMMANDS = [
    // Delimiters
    'langle', 'rangle', 'lceil', 'rceil', 'lfloor', 'rfloor', 'vert', 'Vert', 'backslash', 'lbrace', 'rbrace',
    // Core math symbols & binary relations
    'ell', 'wp', 'Re', 'Im', 'partial', 'infty', 'prime', 'emptyset', 'nabla', 'surd', 'top', 'bot', 'angle', 'forall', 'exists', 'neg', 'flat', 'natural', 'sharp',
    'clubsuit', 'diamondsuit', 'heartsuit', 'spadesuit',
    'pm', 'mp', 'times', 'div', 'ast', 'star', 'circ', 'bullet', 'cdot', 'cap', 'cup', 'uplus', 'sqcap', 'sqcup', 'triangleleft', 'triangleright', 'wr', 'bigcirc', 'bigtriangleup', 'bigtriangledown', 'vee', 'wedge', 'oplus', 'ominus', 'otimes', 'oslash', 'odot', 'dagger', 'ddagger', 'amalg',
    'leq', 'geq', 'equiv', 'models', 'prec', 'succ', 'sim', 'perp', 'preceq', 'succeq', 'simeq', 'mid', 'll', 'gg', 'asymp', 'parallel', 'subset', 'supset', 'approx', 'bowtie', 'subseteq', 'supseteq', 'cong', 'sqsubset', 'sqsupset', 'neq', 'smile', 'sqsubseteq', 'sqsupseteq', 'doteq', 'frown', 'in', 'ni', 'notin', 'propto', 'vdash', 'dashv',
    // Arrows
    'leftarrow', 'Leftarrow', 'rightarrow', 'Rightarrow', 'leftrightarrow', 'Leftrightarrow', 'mapsto', 'hookleftarrow', 'hookrightarrow', 'longleftarrow', 'Longleftarrow', 'longrightarrow', 'Longrightarrow', 'longleftrightarrow', 'Longleftrightarrow', 'longmapsto', 'uparrow', 'Uparrow', 'downarrow', 'Downarrow', 'updownarrow', 'Updownarrow', 'nearrow', 'searrow', 'swarrow', 'nwarrow', 'iff', 'to', 'gets',
    // Dots
    'dots', 'ldots', 'cdots', 'vdots', 'ddots', 'colon',
    // Accents & decorations
    'hat', 'widehat', 'check', 'tilde', 'widetilde', 'acute', 'grave', 'dot', 'ddot', 'breve', 'bar', 'vec', 'mathring', 'overline', 'underline', 'overbrace', 'underbrace',
    // Font sizing & switches
    'mathrm', 'mathbf', 'mathit', 'mathsf', 'mathtt', 'mathcal', 'text', 'textbf', 'textit', 'textrm', 'textsf', 'texttt', 'textsc', 'emph', 'scshape', 'bfseries', 'itshape', 'upshape', 'Huge', 'huge', 'LARGE', 'Large', 'large', 'normalsize', 'small', 'footnotesize', 'scriptsize', 'tiny',
    // Spacing & TeX primitives
    'mkern', 'kern', 'mskip', 'hskip', 'vskip', 'hspace', 'vspace', 'quad', 'qquad', 'phantom', 'vphantom', 'hphantom', 'smash', 'relax', 'hbox', 'vbox', 'vtop', 'par', 'indent', 'noindent', 'penalty', 'unskip', 'ignorespaces', 'leavevmode', 'allowbreak', 'centering', 'raggedright', 'raggedleft',
    // Core references
    'pageref'
  ];
  for (const cmd of CORE_LATEX_COMMANDS) {
    validCommands.add(cmd);
    knownCommandNames.push(cmd);
  }

  // Add any macros confirmed valid by TeX engine compilation of this revision
  if (options.compiledCleanMacros && typeof options.compiledCleanMacros.forEach === 'function') {
    options.compiledCleanMacros.forEach((m) => validCommands.add(m));
  }

  // Standard core packages that do not define custom macro suites
  const KNOWN_STANDARD_PACKAGES = new Set([
    'inputenc', 'fontenc', 'babel', 'lmodern', 'textcomp',
    'microtype', 'csquotes', 'indentfirst', 'cmap', 'fixltx2e',
    'array', 'float', 'caption', 'subcaption', 'enumitem',
    'url', 'cite', 'amsthm', 'tabularx', 'fontspec', 'amssymb', 'amsfonts', 'booktabs', 'geometry'
  ]);

  // Package aliases & bundled relationships
  const effectivePackages = new Set(loadedPackages);
  if (effectivePackages.has('amsthm')) effectivePackages.add('mathtools');
  if (effectivePackages.has('mathtools')) effectivePackages.add('amsmath');
  if (effectivePackages.has('amssymb')) effectivePackages.add('amsfonts');
  if (effectivePackages.has('pgfplotstable')) effectivePackages.add('pgfplots');
  if (
    effectivePackages.has('pgfplots') ||
    effectivePackages.has('circuitikz') ||
    effectivePackages.has('forest') ||
    effectivePackages.has('tcolorbox') ||
    effectivePackages.has('tikz-cd')
  ) {
    effectivePackages.add('tikz');
  }
  if (effectivePackages.has('tikz')) {
    effectivePackages.add('xcolor');
    effectivePackages.add('graphicx');
  }
  if (effectivePackages.has('beamer')) {
    effectivePackages.add('tikz');
    effectivePackages.add('xcolor');
    effectivePackages.add('hyperref');
    effectivePackages.add('graphicx');
  }
  if (effectivePackages.has('subcaption')) {
    effectivePackages.add('caption');
  }
  if (effectivePackages.has('amsart') || effectivePackages.has('amsbook') || effectivePackages.has('amsproc')) {
    effectivePackages.add('amsmath');
    effectivePackages.add('amssymb');
    effectivePackages.add('amsthm');
    effectivePackages.add('amsfonts');
    effectivePackages.add('mathtools');
  }

  // Package-specific additions
  if (effectivePackages.has('amsthm') || effectivePackages.has('mathtools')) {
    ['theoremstyle', 'newtheoremstyle', 'swapnumbers', 'qed', 'qedsymbol', 'openbox', 'theorembodyfont', 'theoremheaderfont'].forEach(c => {
      validCommands.add(c);
      knownCommandNames.push(c);
    });
    validEnvironments.add('proof');
  }

  if (effectivePackages.has('amsmath') || effectivePackages.has('mathtools')) {
    ['DeclareMathOperator', 'operatorname', 'tag', 'notag', 'nonumber', 'intertext', 'shortintertext', 'eqref', 'implies', 'impliedby'].forEach(c => {
      validCommands.add(c);
      knownCommandNames.push(c);
    });
  }

  if (effectivePackages.has('amssymb') || effectivePackages.has('amsfonts')) {
    ['hbar', 'mathbb', 'mathfrak', 'checkmark', 'circledR', 'maltese'].forEach(c => {
      validCommands.add(c);
      knownCommandNames.push(c);
    });
  }

  if (effectivePackages.has('siunitx')) {
    [
      'SI', 'si', 'sisetup', 'num', 'ang', 'qty', 'unit', 'qtyrange', 'numrange', 'SIrange',
      'complexnum', 'complexqty', 'qtylist', 'numlist', 'tablenum', 'DeclareSIUnit',
      'micro', 'percent', 'celsius', 'ohm', 'hertz', 'meter', 'metre', 'second',
      'watt', 'joule', 'volt', 'ampere', 'kelvin', 'kilo', 'milli', 'nano', 'pico', 'mega', 'giga'
    ].forEach(c => {
      validCommands.add(c);
      knownCommandNames.push(c);
    });
  }

  if (effectivePackages.has('pgfplots')) {
    ['pgfplotsset', 'usepgfplotslibrary', 'addplot', 'addlegendentry', 'legend', 'pgfplotssetlayers', 'pgfplotsinvokeforeach'].forEach(c => {
      validCommands.add(c);
      knownCommandNames.push(c);
    });
    ['axis', 'semilogxaxis', 'semilogyaxis', 'loglogaxis', 'groupplot'].forEach(e => validEnvironments.add(e));
  }

  if (effectivePackages.has('tabularx')) {
    validEnvironments.add('tabularx');
  }

  // Check if every loaded package is known in the DB
  const dbPackages = new Set([...db.packages, ...db.macros.map(m => m.package)]);
  let allLoadedPackagesKnown = true;
  for (const pkg of loadedPackages) {
    if (pkg !== 'latex2e' && !dbPackages.has(pkg) && !KNOWN_STANDARD_PACKAGES.has(pkg)) {
      allLoadedPackagesKnown = false;
      break;
    }
  }

  for (const macro of db.macros) {
    knownCommandNames.push(macro.name);
    if (macro.package === 'latex2e' || effectivePackages.has(macro.package)) {
      validCommands.add(macro.name);
    }
  }

  for (const env of db.environments) {
    if (env.package === 'latex2e' || effectivePackages.has(env.package)) {
      validEnvironments.add(env.name);
    }
  }

  // Pre-calculate line start offsets for l.<line> reporting
  const lines = text.split('\n');
  const lineStarts = [0];
  for (let i = 0; i < lines.length - 1; i++) {
    lineStarts.push(lineStarts[i] + lines[i].length + 1);
  }
  function getLineNumber(offset) {
    let low = 0, high = lineStarts.length - 1;
    while (low <= high) {
      const mid = (low + high) >> 1;
      if (lineStarts[mid] <= offset) {
        if (mid === lineStarts.length - 1 || lineStarts[mid + 1] > offset) return mid + 1;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return 1;
  }

  // Mask regions: comments and verbatim
  const len = text.length;
  const isMasked = new Uint8Array(len);

  // Mask % comments
  for (let i = 0; i < len; i++) {
    if (text[i] === '%') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        while (i < len && text[i] !== '\n') { isMasked[i] = 1; i++; }
      }
    }
  }

  // Mask verbatim blocks
  const verbEnvRegex = /\\begin\{(?:verbatim|lstlisting|minted)\}[\s\S]*?\\end\{(?:verbatim|lstlisting|minted)\}/g;
  let vm;
  while ((vm = verbEnvRegex.exec(text)) !== null) {
    for (let k = vm.index; k < vm.index + vm[0].length; k++) isMasked[k] = 1;
  }

  // 1. Check commands: \\[a-zA-Z@]+\*?
  const cmdRegex = /\\([a-zA-Z@]+)\*?/g;
  let cm;
  while ((cm = cmdRegex.exec(text)) !== null) {
    const from = cm.index;
    const to = from + cm[0].length;
    if (isMasked[from]) continue;

    // Ignore plain words immediately following a TeX \\ linebreak (e.g. \\Name)
    let prevBackslashes = 0;
    let backIdx = from - 1;
    while (backIdx >= 0 && text[backIdx] === '\\') {
      prevBackslashes++;
      backIdx--;
    }
    if (prevBackslashes % 2 === 1) continue;

    const cmdName = cm[1];
    // Skip definition commands themselves
    if (
      cmdName === 'newcommand' ||
      cmdName === 'renewcommand' ||
      cmdName === 'providecommand' ||
      cmdName === 'def' ||
      cmdName === 'let' ||
      cmdName === 'newenvironment' ||
      cmdName === 'renewenvironment' ||
      cmdName === 'newcounter'
    ) {
      continue;
    }

    if (!validCommands.has(cmdName)) {
      const lineNum = getLineNumber(from);
      // Find nearest known command (Levenshtein <= 2)
      let bestMatch = null;
      let minDistance = 3;

      for (const known of knownCommandNames) {
        const d = levenshteinDistance(cmdName, known);
        if (d < minDistance) {
          minDistance = d;
          bestMatch = known;
          if (d === 1) break;
        }
      }

      // Policy: false positive is worse than missed error.
      // If minDistance === 0, it is a known LaTeX command from the database.
      if (minDistance === 0) {
        const macroInfo = db.macros.find(m => m.name === cmdName);
        if (macroInfo && macroInfo.package && macroInfo.package !== 'latex2e' && !effectivePackages.has(macroInfo.package)) {
          diagnostics.push({
            from: from,
            to: to,
            severity: 'error',
            line: lineNum,
            message: `! Package required: \\${cmdName} requires \\usepackage{${macroInfo.package}}`,
            actions: []
          });
        }
        continue;
      }

      // If document uses packages not in DB, only flag if within Levenshtein <= 2 of known command.
      if (!allLoadedPackagesKnown && minDistance > 2) {
        continue;
      }

      const actions = [];
      let fixNotice = '';
      if (bestMatch && minDistance <= 2) {
        actions.push({
          name: `Did you mean \\${bestMatch}?`,
          apply(view, fromOffset, toOffset) {
            view.dispatch({ changes: { from: fromOffset, to: toOffset, insert: `\\${bestMatch}` } });
          }
        });
        fixNotice = ` Did you mean \\${bestMatch}?`;
      }

      diagnostics.push({
        from: from,
        to: to,
        severity: 'error',
        line: lineNum,
        message: `! Undefined control sequence. l.${lineNum} \\${cmdName}.${fixNotice}`,
        actions: actions
      });
    }
  }

  // 2. Check matched \begin{env} and \end{env}
  const envStack = [];
  const envTagRegex = /\\(begin|end)\{([a-zA-Z0-9*_-]+)\}/g;
  let em;
  while ((em = envTagRegex.exec(text)) !== null) {
    const from = em.index;
    const to = from + em[0].length;
    if (isMasked[from]) continue;

    const kind = em[1];
    const envName = em[2];
    const lineNum = getLineNumber(from);

    if (kind === 'begin') {
      envStack.push({ name: envName, from, to, line: lineNum });
    } else {
      if (envStack.length === 0) {
        diagnostics.push({
          from: from,
          to: to,
          severity: 'error',
          line: lineNum,
          message: `! LaTeX Error: \\end{${envName}} without matching \\begin{${envName}}.`
        });
      } else {
        const last = envStack.pop();
        if (last.name !== envName) {
          diagnostics.push({
            from: from,
            to: to,
            severity: 'error',
            line: lineNum,
            message: `! LaTeX Error: \\begin{${last.name}} on line ${last.line} ended by \\end{${envName}} on line ${lineNum}.`
          });
        }
      }
    }
  }

  // Unclosed \begin{env} remaining on stack
  for (const unclosed of envStack) {
    diagnostics.push({
      from: unclosed.from,
      to: unclosed.to,
      severity: 'error',
      line: unclosed.line,
      message: `! LaTeX Error: \\begin{${unclosed.name}} on line ${unclosed.line} not closed.`
    });
  }

  // 3. Unbalanced braces outside comments/verbatim
  let braceDepth = 0;
  let lastOpenBracePos = 0;
  for (let i = 0; i < len; i++) {
    if (isMasked[i]) continue;
    if (text[i] === '{') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        braceDepth++;
        lastOpenBracePos = i;
      }
    } else if (text[i] === '}') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        braceDepth--;
        if (braceDepth < 0) {
          const lineNum = getLineNumber(i);
          diagnostics.push({
            from: i,
            to: i + 1,
            severity: 'error',
            line: lineNum,
            message: `! Extra }, or forgotten \\endgroup on line ${lineNum}.`
          });
          braceDepth = 0;
        }
      }
    }
  }

  if (braceDepth > 0) {
    const lineNum = getLineNumber(lastOpenBracePos);
    diagnostics.push({
      from: lastOpenBracePos,
      to: lastOpenBracePos + 1,
      severity: 'error',
      line: lineNum,
      message: `! Missing } inserted for brace opened on line ${lineNum}.`
    });
  }

  return diagnostics;
}

module.exports = {
  lintLatexDocument,
  extractLoadedPackages,
  extractLocalDefinitions,
  levenshteinDistance
};
